function restrictClassCards(){
 for(let id=0;id<CLASS_SKILLS.length;id++)CLASS_SKILLS[id]=CLASS_SKILLS[id].filter(k=>!Object.hasOwn(RETIRED_CLASS_SKILLS,k));
 const allowed=new Set(CLASS_SKILLS.flat());
 for(const key of Object.keys(C))if(!allowed.has(key))delete C[key];
 HEROES.forEach((hero,id)=>{hero.starter=[];hero.gift=['siphon','rain','ignite','knightjudgment','priestoracle','sel_charge'][id]});
 const replacements={berserk:'desperation',detonate:'ignite',meteorfall:'skyfire',inferno:'ignite',nova:'coldrelease',charge:'staticcharge',stance:'defense',bloodthirst:'siphon',bloodslash:'siphon',strike:'heavy',guard:'defense',bash:'shieldbash',wall:'defense',haste:'quickshot',barrage:'infinite',volley:'double',pierce:'penetrate',scout:'aim',flow:'tempo',wind:'quickshot',spark:'fireball',ice:'frostbolt',thunder:'chain',meteor:'skyfire',grand:'cataclysm',blizzard:'nova',storm:'chain',focus:'resonance'};
 const current=keys=>[...new Set(keys.map(k=>RETIRED_CLASS_SKILLS[k]||replacements[k]||k).filter(k=>allowed.has(k)))];
 for(const key of Object.keys(GEAR_LINKS))GEAR_LINKS[key]=current(GEAR_LINKS[key]);
 for(const build of BUILDS)build.cards=current(build.cards);
 const healing=BUILDS.find(b=>b.name==='聖癒誓約');if(healing)healing.desc='普攻持續治療 → 強化聖療 → 救贖保住低血隊友';
 const rescue=BUILDS.find(b=>b.name==='救贖守護');if(rescue)rescue.desc='預先留下救贖 → 致命傷保命治療 → 血契強化普攻';
}
