function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function alive(){return s.party.map((p,i)=>p.hp>0?i:-1).filter(i=>i>=0)}
function totalHP(){return s.party.reduce((n,p)=>n+p.hp,0)}
function log(t){messages.unshift(t);messages=messages.slice(0,5);recordBattleEvent(t)}
let combatSaveTimer=null,combatSaveOwner=null,combatSaveAt=-Infinity;
function scheduleCombatSave(){if(s.phase!=='battle'||combatSaveOwner!==s.auto||Date.now()-combatSaveAt>=750){save();return}if(!combatSaveTimer)combatSaveTimer=setTimeout(()=>{combatSaveTimer=null;save()},Math.max(0,750-(Date.now()-combatSaveAt)))}
if(typeof globalThis.addEventListener==='function')globalThis.addEventListener('pagehide',()=>save());
if(typeof document.addEventListener==='function')document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});
function save(){if(typeof syncExpeditionMetrics==='function')syncExpeditionMetrics();if(combatSaveTimer){clearTimeout(combatSaveTimer);combatSaveTimer=null}combatSaveOwner=s.auto;combatSaveAt=Date.now();if(s.training){saveTrainingConfig(s.training.config);return}try{localStorage.setItem('ember-v3',JSON.stringify({version:3,s:{...s,enemy:enemyRoster().find(e=>e.id===s.targetEnemyId)||s.enemy},messages}));$('savewarning').hidden=true}catch{$('savewarning').hidden=false}}
function validRoster(ids){return Array.isArray(ids)&&ids.length===3&&new Set(ids).size===3&&ids.every(i=>Number.isInteger(i)&&HEROES[i])}
// Lower position values stand closer to the enemy; selection order never sets formation.
function sortHeroPositions(ids){return [...ids].sort((a,b)=>(HEROES[a]?.position??1000)-(HEROES[b]?.position??1000)||a-b)}
function applyPartyPositions(state){
 if(!Array.isArray(state.party))return;
 const previous=[...state.party],order=sortHeroPositions(previous.map(p=>p.id));
 const remap=slot=>Number.isInteger(slot)&&previous[slot]?order.indexOf(previous[slot].id):slot;
 state.selected=remap(state.selected);
 if(Array.isArray(state.acted))state.acted=state.acted.map(remap);
 for(const enemy of new Set([state.enemy,...(state.enemies||[])]))if(enemy)enemy.target=remap(enemy.target);
 state.party=order.map(id=>previous.find(p=>p.id===id));state.picks=[...order];
}
function heroAt(slot){return HEROES[s.party[slot]?.id]}
function slotOf(id){return s.party.findIndex(p=>p.id===id)}
function inParty(id){return slotOf(id)>=0}
function cardPool(){return Object.keys(C).filter(k=>k!=='pair'&&inParty(C[k].owner))}
function giftKey(){return HEROES[s.party[s.party.length-1].id].gift}
