 if(c.job==='whirlwind')return ['3 秒全體旋風斬','斬 '+hits[0][1]+' ×6 · 首末各流血 +1'];if(c.job==='rain')return ['蓄力 1 秒 · 3 秒 9 箭','不觸發普攻效果'];
 const lines=c.castTime?['詠唱 '+c.castTime/1000+' 秒']:[];
 lines.push(c.job==='cataclysm'?'三元素各 3 秒 · 每秒 '+hits[0][1]:(c.chain?'連鎖 4 敵 · 首段 ':'')+damage);
 const effects=[];if(c.burnStack)effects.push('燃燒 '+c.burnStack+' 層');else if(c.burn)effects.push('燃燒 '+c.burn+'/秒');if(c.slow)effects.push('減速 '+Math.round(c.slow*100)+'%');if(c.freeze)effects.push('凍結 '+c.freeze/1000+' 秒');if(c.stun)effects.push('暈眩 '+c.stun/1000+' 秒');if(c.detonate)effects.push('引爆燃燒 ×260%');if(c.heal)effects.push('治療 +'+c.heal);if(c.healSelf)effects.push('自療 +'+c.healSelf);if(c.block)effects.push('護甲 +'+c.block);if(c.partyBlock)effects.push('全隊護甲 +'+c.partyBlock);if(c.draw)effects.push('抽 '+c.draw+' 張');if(c.lifesteal)effects.push('吸血 '+Math.round(c.lifesteal*100)+'%');if(c.grandMagic)effects.push('三符文 ×2');if(c.job==='cataclysm')return [...lines,'燃燒／凍結／暈眩 · 三符文 ×2'];
