function card(k,action,disabled=false){let c=C[k],cost=(typeof mageEffectiveCost==='function'?mageEffectiveCost(c):c.cost);return `<button class="card ${c.type} hero-${c.owner??'pair'} painted-rarity rarity-${cardFrameRarity(c)}" style="${cardMotionStyle(k)}" onclick="${action}" ${disabled?'disabled':''} aria-label="${c.name}，${ownerLabel(c)}，${cost} 能量，${c.desc}">${cardFrameHTML(c)}<span class="cost">${cost}</span><h3 class="card-title${c.name.length>5?' card-title-long':''}">${c.name}</h3><small class="card-owner">${ownerLabel(c)} · ${cardRarity(k)}</small><span class="card-art portrait-${c.owner??'pair'}"><span class="card-art-aura" aria-hidden="true">${rasterFXHTML(c.owner===0?'rageaura':c.owner===1?'speedaura':'chant',{duration:2400})}</span><i class="painted-skill">${skillIconHTML(k)}</i><span class="card-art-motes" aria-hidden="true">${rasterFXHTML('dust',{duration:1800})}</span></span><div class="card-attrs">${c.area?'<span class="support-tag area-tag">全體範圍</span>':''}${c.knightPath?'<span class="support-tag knight-form-tag">'+knightCardTypeName(c.knightPath)+'</span>':attrsHTML((c.hits||[]).map(h=>h[0]))||'<span class="support-tag">支援</span>'}</div><div class="card-content"><p class="card-short-description" title="${c.desc}">${cardRulesHTML(k)}</p>${cardGearHint(k)}</div></button>`}
