 const allowed=new Set(CLASS_SKILLS.flat()),old=(t.deck||[]).filter(k=>allowed.has(k)&&t.party.some(p=>p.id===C[k].owner));
 t.collection=(t.collection||[]).filter(k=>allowed.has(k));
 for(const k of new Set(old))while(t.collection.filter(x=>x===k).length<old.filter(x=>x===k).length)t.collection.push(k);
 t.pairUnlocked=false;t.bond=0;
 t.deck=t.party.flatMap(p=>old.filter(k=>C[k].owner===p.id).slice(0,DECK_CLASS_LIMIT));
 if(t.deckRevision!==3){
  for(const p of t.party)if(!t.deck.some(k=>C[k].owner===p.id)){const cards=rollStarterCards(p.id);t.deck.push(...cards);t.collection.push(...cards)}
  if(t.phase==='battle'){
   const remaining=[...t.deck];
   for(const key of ['hand','draw','discard'])if(Array.isArray(t[key]))t[key]=t[key].filter(k=>{const i=remaining.indexOf(k);if(i<0)return false;remaining.splice(i,1);return true});
   if(Array.isArray(t.draw))t.draw.push(...remaining);
  }
 }
 for(const key of ['hand','draw','discard','rewards'])if(Array.isArray(t[key]))t[key]=t[key].filter(k=>allowed.has(k));
