function selectDeckReserve(k){if(!deckEditable()||!C[k]||!inParty(C[k].owner)||spareCardCount(k)<=0)return;if(deckSlot!==-1&&deckSlotOwner(deckSlot)===C[k].owner){replaceDeckCard(deckSlot,k);return}deckPick=deckPick===k?null:k;showDeck(String(C[k].owner))}
