function deckDragStart(event,k){if(!deckEditable()||spareCardCount(k)<=0){event.preventDefault();return}deckDragKey=k;event.dataTransfer.setData('text/plain',k);event.dataTransfer.effectAllowed='copy';deckPick=k;document.querySelectorAll('[data-deck-slot]').forEach(el=>el.classList.toggle('drop-ready',deckSlotOwner(Number(el.dataset.deckSlot))===C[k].owner))}
