 const move=e=>{moved=true;ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-deck-slot]');document.querySelectorAll('[data-deck-slot]').forEach(el=>el.classList.toggle('drop-hover',el===target&&deckSlotOwner(Number(el.dataset.deckSlot))===C[k].owner));const dialog=$('modal'),box=dialog.getBoundingClientRect();if(e.clientY<box.top+65)dialog.scrollTop-=18;else if(e.clientY>box.bottom-65)dialog.scrollTop+=18};
 const finish=e=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',finish);ghost.remove();deckDragEnd();if(e.type==='pointerup'&&moved&&target){deckPick=null;replaceDeckCard(Number(target.dataset.deckSlot),k)}else if(e.type==='pointerup')selectDeckReserve(k)};
