 const reserve=`<section class="deck-reserve"><h3>備用收藏 <span>${choices.length} 種可換入</span></h3><div class="deck-reserve-grid">${choices.map(k=>`<article class="reserve-card ${deckPick===k?'picked':''}" draggable="${editable}" ondragstart="deckDragStart(event,'${k}')" ondragend="deckDragEnd()"><button class="reserve-select" onclick="selectDeckReserve('${k}')" ${editable?'':'disabled'} aria-pressed="${deckPick===k}">${skillIconHTML(k)}<b>${C[k].name}</b><small>${HEROES[C[k].owner].job} · 備用 ×${spareCardCount(k)} · ${C[k].cost} 能量</small><span>${cardFaceLines(k).join(' · ')}</span></button><button class="deck-drag-handle" onpointerdown="deckTouchDrag(event,'${k}')" ${editable?'':'disabled'} aria-label="拖曳${C[k].name}換牌">⠿ 拖曳換牌</button></article>`).join('')||'<p class="deck-empty">目前沒有備用卡。戰後獎勵或商店取得的卡牌會放在這裡。</p>'}</div></section>`;
