function updateBond(){return false}
function play(i){if(s.phase!=='battle'||busy||s.auto?.paused)return;let k=s.hand[i],c=C[k];if(!c||!canUse(c)||(typeof mageEffectiveCost==='function'?mageEffectiveCost(c):c.cost)>s.energy)return;const origin=capturePlayedCard(i);if(CLASS_SKILLS.flat().includes(k)||c.owner===2&&c.hits?.length||c.owner===1&&c.hits?.some(h=>h[0]==='pierce')){castClassSkill(i,origin);return}s.energy-=c.cost;s.hand.splice(i,1);s.discard.push(k);const hits=(c.hits||[]).map(([a,n])=>[a,c.grandMagic&&s.auto.runes.length===3?n*2:n]);let e=s.enemy,attackTarget=e.id,{damage,shieldHits,newBreak,criticalHits}=damageEnemy(hits,c.owner,{lifesteal:c.lifesteal,card:c,owners:c.owners});if(c.block)s.party[slotOf(c.owner)].block+=c.block;if(c.partyBlock)alive().forEach(j=>s.party[j].block+=c.partyBlock);if(c.taunt){s.taunt=true;e.target=slotOf(c.owner)}if(c.heal)healTarget(c.heal,s.party[s.selected]?.hp>0?s.selected:undefined,c.owner??s.party[s.selected]?.id);if(c.healSelf)healTarget(c.healSelf,slotOf(c.owner),c.owner);if(c.partyHeal)alive().forEach(j=>healTarget(c.partyHeal,j,c.owner??s.party[s.selected]?.id));if(c.strength)s.strength+=c.strength;if(c.reveal){let hidden=e.weak.filter(a=>!e.known.includes(a));if(hidden.length)reveal(hidden[0]);else log('此敵人的所有弱點已揭露。')}if(c.draw)draw(c.draw);applyCardExtras(c);let unlocked=updateBond(c);log(ownerLabel(c)+'使出「'+c.name+'」'+(damage?'，'+damage+' 傷害':'')+(shieldHits?'／削盾 '+shieldHits:'')+'。');if(e.hp===0)victory();animateCard(c,damage,newBreak,unlocked,attackTarget,origin,[],criticalHits)}
