function victory(){if(s.training||s.phase!=='battle')return;resolveEnemyDeaths();if(s.phase==='dead'||livingEnemies().length)return;clearWarriorExpansion();s.auto.jobs=[];delete s.auto.casting;delete s.auto.castings;delete s.auto.castVisuals;delete s.auto.castVisual;delete s.auto.earth;delete s.auto.lightning;delete s.auto.frost;delete s.auto.fire;delete s.auto.mageForm;delete s.auto.magePassives;s.party.forEach(p=>{delete p.permanentQuickshot;delete p.pactStacks;p.buffs={}});if(s.battleStats)s.battleStats.complete=true;gearLoot(s.enemy.type);const boss=s.enemy.type==='首領',chapter=currentStage().chapter,coins=(boss?70:s.enemy.type==='精英'?45:25)+chapter*10;s.gold+=coins;alive().forEach(i=>healTarget(boss?12:3,i));if(boss&&s.floor===route.length-1&&typeof endgameVictory==='function'&&endgameVictory())return;if(boss&&s.floor===route.length-1){s.phase='win';log('燼龍王倒下。三章遠征完成，三人的羈絆迎來黎明。');return}if(s.enemy.type==='精英'){s.relic++;log('獲得「灰燼徽記」：每 12 秒每位存活隊員 +2 護甲。')}s.phase='reward';s.rewards=synergyRewards();log(boss?(chapterClear()?currentChapter().name+'已突破！前往下一章。':'小首領已擊敗，繼續深入本章。')+'獲得首領裝備、'+coins+' 金幣。':'戰鬥勝利！獲得 '+coins+' 金幣，存活隊員恢復 3 生命。')}
function reward(k){if(s.phase!=='reward'||busy||k&&!s.rewards.includes(k))return;if(k)collectCard(k);advance()}
