function camp(which){if(s.phase!=='營火'||busy||![1,2].includes(which))return;if(which===1){const full=currentStage().sanctuary;s.party.forEach(p=>p.hp=full?p.max:Math.min(p.max,p.hp+24));log(full?'章節補給：全隊完全恢復生命，倒下成員復活。':'營火休息：全隊恢復 24 生命，倒下成員復活。')}else{s.party.forEach(p=>{p.max+=6;if(p.hp>0)p.hp=Math.min(p.max,p.hp+6)});log('全隊生命上限 +6，存活成員恢復 6 生命。')}if(s.party[s.selected].hp<=0)s.selected=alive()[0];advance()}
function shopKeys(){return merchantCardKeys()}
function buy(k){if(s.phase!=='商店'||busy||s.gold<35||!shopKeys().includes(k)||!s.cardShop.revealed||s.cardShop.purchasedKey||shopRevealActive())return;const origin=captureShopPurchase('card',k);s.cardShop.purchasedKey=k;s.gold-=35;collectCard(k);const receipt=registerShopPurchase('card',k,35);log('購買「'+C[k].name+'」，已獲得；同職業空位自動補入，滿額後可在牌組介面替換。');render();showShopPurchase(receipt,origin)}
