 fx.innerHTML=`<div class="fx-flare">${rasterFXHTML('reveal',{loop:false,duration:950,age:0})}</div><div class="cutin">${owners.map(i=>`<div class="cutin-portrait portrait-${i}">${characterArtHTML(i)}</div>`).join('')}<div class="cutin-title">${skillIconHTML(cardKeyOf(c),'cutin-skill-icon')}<small>${pair?'PAIR SKILL · 羈絆共鳴':ownerLabel(c)+' · '+ATTR[attr].name}</small><strong>${c.name}</strong><span>${isBreak?ailmentIconHTML('break','break-cutin-icon')+'BREAK! · ':''}${damage?damage+' 傷害':''}</span></div></div>${pair?'<div class="ultimate-ring">'+rasterFXHTML('targetfocus',{loop:false,duration:1350,age:0})+'</div><div class="slash-beam">'+rasterFXHTML('slash',{loop:false,duration:1350,age:0})+'</div>':''}${unlocked?'<div class="unlock-toast">羈絆達標 · 爆炎烈斬解鎖！</div>':''}`;
