function renderParty(){return s.party.map((p,i)=>`<button class="hero ${heroAt(i).className} ${p.hp<=0?'fallen':''} ${s.selected===i?'selected':''}" onclick="selectHero(${i})" ${p.hp<=0?'disabled':''} aria-pressed="${s.selected===i}" aria-label="${heroAt(i).name}，${heroAt(i).role}，生命 ${p.hp}/${p.max}，點選設定療癒對象"><div class="hero-portrait portrait-${p.id}">${headshotHTML(p.id)}</div><div class="hero-info"><small>${['前排','中排','後排'][i]} · ${heroAt(i).job}</small><h2>${heroAt(i).name} <span>${p.hp<=0?'倒下':s.selected===i?'療癒對象':''}</span></h2>${gearSummary(p)}${healthGaugeHTML('hero:'+p.id,p.hp,p.max)}<div class="hero-numbers"><b>♥ ${p.hp}<span> / ${p.max}</span></b><small>◈ ${p.block} 護甲</small></div>${resourceHUD(p)}${criticalHUD(p)}</div></button>`).join('')}
function weaknessHTML(e){return e.weak.map(a=>e.known.includes(a)?`<span class="weak revealed" style="--attr:${ATTR[a].color}" title="已知弱點：${ATTR[a].name}">${attributeIconHTML(a)}<small>${ATTR[a].name}</small></span>`:'<span class="weak hidden" title="未知弱點">？<small>未知</small></span>').join('')}
function enemyArt(e){return enemySpriteHTML(e)}
let combatEntryKey=null;
function updateCombatLayout(){const travel=!!sceneMotion?.travel,combat=s.phase==='battle'||!!(sceneMotion&&s.enemy&&!travel);$('combat-workspace').dataset.mode=travel?'travel':combat?'battle':'rest';const entering=s.phase==='battle'||travel;if(!entering){combatEntryKey=null;return}const key=s.floor+':'+(travel?'travel':'battle');if(key===combatEntryKey)return;combatEntryKey=key;if(typeof window!=='undefined'&&typeof window.scrollTo==='function')window.scrollTo({top:0,left:0,behavior:'instant'})}
function render(){if(typeof clearCombatHTMLCache==='function')clearCombatHTMLCache();if(typeof captureRangerVFXLayer==='function')captureRangerVFXLayer();const priorCamera=document.querySelector?.('.battle-camera'),battlePan=priorCamera?.dataset?.battleFloor===String(s.floor)&&!sceneMotion?.travel?{left:priorCamera.scrollLeft,top:priorCamera.scrollTop}:null;if(s.training?.config.infiniteEnergy)s.energy=5;initFixedDeck(s);updateCombatLayout();seedBestiary(s);syncShopFeedback();initEquipment(s);if(s.phase==='事件')prepareCampaignEvent();captureHUD();if(s.phase==='商店'){prepareGearShop();prepareCardShop()}scheduleCombatSave();$('progress').textContent=s.training?'訓練場 · 無限生命假人':s.phase==='recruit'?'3 職業 · 三人小隊':'第 '+(currentStage().chapter+1)+' 章 · '+Math.min(s.floor+1,route.length)+' / '+route.length+' 層 · '+(s.phase==='win'?'已完成':route[s.floor]);$('stats').innerHTML=`<div class="stat"><small>小隊生命</small><b>♥ ${totalHP()} <span>/ ${s.party.reduce((n,p)=>n+p.max,0)}</span></b>${healthGaugeHTML('team',totalHP(),s.party.reduce((n,p)=>n+p.max,0))}</div><div class="stat"><small>金幣 / 遺物</small><b>◉ ${s.gold} <span>／ ❖ ${s.relic}</span></b></div>`;$('party').innerHTML=renderParty();$('bond').hidden=true;$('deckcount').textContent=s.training?s.deck.length+' 張測試卡':s.deck.length+' / '+s.party.length*DECK_CLASS_LIMIT;$('hand').innerHTML='';$('hand-panel').hidden=!(s.phase==='battle'||sceneMotion&&s.enemy&&!sceneMotion.travel);$('piles').textContent='牌組 '+s.deck.length+' 張 · 自動存檔';$('end').style.display=s.phase==='battle'?'block':'none';$('end').disabled=false;$('redraw').style.display=s.phase==='battle'?'block':'none';$('redraw').disabled=busy||s.auto?.paused||s.energy<1||(s.auto?.clock||0)<(s.auto?.redrawAt||0);$('end').textContent=s.auto?.paused?'▶ 繼續戰鬥':'Ⅱ 暫停戰鬥';let html='';if(s.phase==='recruit'){html=recruitHTML()}else if(sceneMotion?.travel){html=stageTravelHTML()}else if(s.phase==='battle'||sceneMotion&&s.enemy){let e=s.enemy;html=battleHTML(e);$('hand').innerHTML=handPanelHTML();$('piles').textContent='抽牌堆 '+s.draw.length+' · 棄牌堆 '+s.discard.length+' · 每 3 秒回復 1 能量 · 手牌上限 7' }else if(s.phase==='gate'){html=fateGateHTML()}else if(s.phase==='map'){html=campaignMapHTML()}else if(s.phase==='reward'){html=(chapterClear()?'<div class="chapter-clear"><div class="eyebrow">CHAPTER COMPLETE</div><h2>'+currentChapter().name+' · 已突破</h2><p>首領裝備已放入背包。選完卡牌後前往'+(typeof expeditionChapters==='function'?expeditionChapters():CHAPTERS)[currentStage().chapter+1].name+'，可在避風營地完全恢復生命。</p></div>':'<div class="eyebrow">VICTORY · A NEW POSSIBILITY</div><h2>選擇下一份力量。</h2><p>免費選取一張卡牌；同職業未滿 5 張時自動加入出戰牌組，滿額後加入備用收藏；此處不消耗能量，也可跳過保持精簡。</p>')+gearLootHTML()+'<div class="choices">'+s.rewards.map(k=>card(k,"reward('"+k+"')",busy)).join('')+'</div>'+(typeof expeditionRewardHTML==='function'?expeditionRewardHTML():'')+'<button class="continue" onclick="reward(null)">跳過獎勵 →</button>'}else if(s.phase==='事件'){html=campaignEventHTML()}else if(s.phase==='營火'){html=campaignCampHTML()}else if(s.phase==='商店'){html='<div class="eyebrow">THE WANDERING MERCHANT</div><h2>'+currentStage().name+'</h2>'+specialSceneHTML('商店')+'<p>本次隨機販售五張卡牌，每張 35 金幣，每次商店限購一張。免費揭示後再決定購買；本店商品固定，不會因重新開啟而重抽。</p>'+merchantCardsHTML()+gearShopHTML()+'<button class="continue" onclick="advance()">離開商店 →</button>'}else{html=campaignOutcomeHTML()}$('board').dataset.theme=currentChapter().theme;html=(s.phase==='recruit'?'':campaignHeaderHTML())+html;setBattleBoardHTML($('board'),html);if(typeof restoreRangerVFXLayer==='function')restoreRangerVFXLayer();if(battlePan){const camera=document.querySelector?.('.battle-camera');if(camera){camera.scrollLeft=battlePan.left;camera.scrollTop=battlePan.top}}const metrics=battleStatsHTML();$('battle-stats-panel').innerHTML=metrics;$('battle-stats-panel').hidden=!metrics;$('log').innerHTML=messages.map(t=>'<div>'+journalEscape(t)+'</div>').join('');updateBattleJournal();if(typeof updateTrainingUI==='function')updateTrainingUI();updateAutoHUD();if(typeof updateMobileCombat==='function')updateMobileCombat();if(typeof syncMageVFXLayout==='function')syncMageVFXLayout();if(typeof syncMageSchoolLayout==='function')syncMageSchoolLayout();if(typeof syncTitanLayout==='function')syncTitanLayout();if(typeof syncKohakuMeleeLayout==='function')syncKohakuMeleeLayout();syncAutoLoop()}
function validSave(v){return !v?.s?.training&&v?.version===3&&v.s?.version===3&&Array.isArray(v.s.party)&&(v.s.phase==='recruit'?v.s.party.length<=3:v.s.party.length===3)&&new Set(v.s.party.map(p=>p.id)).size===v.s.party.length&&v.s.party.every(p=>HEROES[p.id]&&Number.isFinite(p.hp)&&p.hp>=0&&p.hp<=p.max)&&Array.isArray(v.s.deck)&&v.s.deck.every(k=>C[k])&&['recruit','map','battle','reward','事件','營火','商店','win','dead','gate'].includes(v.s.phase)&&(typeof validEndgameSave==='function'?validEndgameSave(v.s):!v.s.endgame&&v.s.phase!=='gate')&&Number.isInteger(v.s.floor)&&v.s.floor>=0&&v.s.floor<route.length&&(!['battle','reward'].includes(v.s.phase)||v.s.enemy&&Array.isArray(v.s.hand)&&v.s.hand.every(k=>C[k])&&Array.isArray(v.s.draw)&&Array.isArray(v.s.discard))}
function migrateV2(old){if(old?.version!==2||old.s?.party?.length!==3)return null;old.version=3;old.s.version=3;old.s.party.forEach((p,i)=>p.id=i);old.s.picks=[0,1,2];return old}
function migrateRoster(v){if(v?.version!==3||!Array.isArray(v.s?.party))return v;let t=v.s,changed=false,added=[];migrateRetiredClassSkills(t);migrateLiaHealth(t);migrateKnightHealth(t);migrateLightningCards(t);migrateFrostCards(t);migrateFireCards(t);migrateMageSupport(t);if(t.phase==='recruit'){t.party=t.party.filter(p=>HEROES[p.id]);t.picks=t.party.map(p=>p.id)}else{let missing=[0,1,2].filter(id=>!t.party.some(p=>p.id===id));t.party=t.party.map(p=>{if(HEROES[p.id])return p;let id=missing.shift();if(id==null)return p;changed=true;added.push(...HEROES[id].starter);return {id,max:HEROES[id].max,hp:Math.round(HEROES[id].max*Math.min(1,p.hp/p.max)),block:p.block||0}});t.picks=t.party.map(p=>p.id)}for(let key of ['deck','hand','draw','discard','rewards'])if(Array.isArray(t[key]))t[key]=t[key].filter(k=>C[k]);if(changed){t.deck.push(...added);if(Array.isArray(t.discard))t.discard.push(...added)}applyPartyPositions(t);initFixedDeck(t);migrateEnemyArtwork(t);return v}
try{let old=migrateCampaign(migrateRoster(JSON.parse(localStorage.getItem('ember-v3'))));if(!validSave(old))old=migrateCampaign(migrateV2(JSON.parse(localStorage.getItem('ember-v2'))));if(validSave(old)){s=old.s;messages=Array.isArray(old.messages)?old.messages.map(t=>typeof t==='string'?t.replaceAll('雷恩','琥珀').replaceAll('弧光斬','斷鋼斧'):String(t)):[];restoreEncounter(s);migrateAutoCards(s);if(s.phase==='battle'){prepareAuto();animateWalk()}else render()}else newRun()}catch{newRun()}
